105:       b->ptr[2]=(unsigned char)(value>>(16-b->endbit));
106:       if(bits>=24){
107:         b->ptr[3]=(unsigned char)(value>>(24-b->endbit));
108:         if(bits>=32){
109:           if(b->endbit)
110:             b->ptr[4]=(unsigned char)(value>>(32-b->endbit));
111:           else
112:             b->ptr[4]=0;
113:         }
114:       }
115:     }
116:   }
117: 
118:   b->endbyte+=bits/8;
119:   b->ptr+=bits/8;
120:   b->endbit=bits&7;
121:   return;
122:  err:
123:   oggpack_writeclear(b);
124: }
